using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1. GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> => Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

Person? deserialized = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Deserialized: {deserialized}");

// 2. TryGetTypeInfo<T>() — probe without throwing
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? resolvedInfo))
{
    Console.WriteLine($"\nTryGetTypeInfo<Person> succeeded => {resolvedInfo!.Type.Name}");
}

// Now try a type whose metadata is NOT available.
// An options instance with no resolver will fail to resolve any type.
var empty = new JsonSerializerOptions { TypeInfoResolver = null };

if (empty.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? missing))
{
    Console.WriteLine($"Unexpected: resolved => {missing!.Type.Name}");
}
else
{
    Console.WriteLine("\nTryGetTypeInfo<Person> on resolver-less options => not available (no exception thrown)");
}

public record Person(string Name, int Age);

